const Pt=struct{inf:bool,x:i64,y:i64};
fn md(x:i64,p:i64)i64{const r=@rem(x,p);return if(r<0) r+p else r;}
fn prime(p:i64)bool{if(p<2)return false;var d:i64=2;while(d*d<=p):(d+=1){if(@rem(p,d)==0)return false;}return true;}
fn powm(x0:i64,n0:i64,p:i64)i64{var x=md(x0,p);var n=n0;var r:i64=1;while(n>0){if((n&1)!=0)r=@rem(r*x,p);x=@rem(x*x,p);n>>=1;}return r;}
fn add(p:i64,a:i64,u:Pt,v:Pt)Pt{if(u.inf)return v;if(v.inf)return u;if(u.x==v.x and md(u.y+v.y,p)==0)return .{.inf=true,.x=0,.y=0};const s=if(u.x==v.x and u.y==v.y) md((3*u.x*u.x+a)*powm(2*u.y,p-2,p),p) else md((v.y-u.y)*powm(v.x-u.x,p-2,p),p);const x=md(s*s-u.x-v.x,p);return .{.inf=false,.x=x,.y=md(s*(u.x-x)-u.y,p)};}
fn mul(p:i64,a:i64,q0:Pt,k0:i64)Pt{var q=q0;var k=k0;var r=Pt{.inf=true,.x=0,.y=0};while(k>0){if((k&1)!=0)r=add(p,a,r,q);k>>=1;if(k>0)q=add(p,a,q,q);}return r;}
fn put(o:[*]u8,k:usize,v:i64)void{const b:@TypeOf(@as(u64,0))=@bitCast(v);for(0..8)|i|o[k+i]=@truncate(b>>@intCast(i*8));}
export fn elliptic_curve_key_exchange(v:?[*]const i64,n:usize,o:?[*]u8,cap:usize)i64{if(n!=7)return -1;const input=v orelse return -1;const p=input[0];const a=input[1];const b=input[2];const x=input[3];const y=input[4];const ka=input[5];const kb=input[6];if(p<5 or p>251 or !prime(p) or a<0 or a>=p or b<0 or b>=p or x<0 or x>=p or y<0 or y>=p or ka<1 or ka>1024 or kb<1 or kb>1024)return -1;if(md(4*a*a*a+27*b*b,p)==0 or md(y*y-x*x*x-a*x-b,p)!=0)return -1;if(cap<48)return -2;const output=o orelse return -2;const g=Pt{.inf=false,.x=x,.y=y};const ap=mul(p,a,g,ka);const bp=mul(p,a,g,kb);const s=mul(p,a,ap,kb);const t=mul(p,a,bp,ka);if(s.inf!=t.inf or (!s.inf and (s.x!=t.x or s.y!=t.y)))return -1;const q=[_]Pt{ap,bp,s};for(0..3)|i|{put(output,i*16,if(q[i].inf)-1 else q[i].x);put(output,i*16+8,if(q[i].inf)-1 else q[i].y);}return 48;}
